import sys
import pytest

class Trace:
    @pytest.hookimpl(hookwrapper=True)
    def pytest_runtest_call(self, item):
        hits = 0
        def profile(frame, event, arg):
            nonlocal hits
            if event == 'call' and frame.f_code.co_name == 'add_replace' and frame.f_code.co_filename.endswith('/src/attr/_make.py'):
                hits += 1
        sys.setprofile(profile)
        try:
            yield
        finally:
            sys.setprofile(None)
            print(f'ADD_REPLACE_HITS {item.nodeid} {hits}')

raise SystemExit(pytest.main(['-q', '-s', 'tests/test_funcs.py::TestEvolve::test_can_change_inst', 'tests/test_funcs.py::TestEvolve::test_private'], plugins=[Trace()]))
